import csv
import calendar
import datetime
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

EMPLOYEES_CSV = "/app/dataset/employees.csv"
TASKS_CSV = "/app/dataset/tasks.csv"
TIMESHEET_CSV = "/app/dataset/timesheet.csv"


def _pesel_checksum_valid(pesel: str) -> bool:
    if len(pesel) != 11 or not pesel.isdigit():
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    digits = [int(c) for c in pesel]
    total = sum(w * d for w, d in zip(weights, digits[:10]))
    control = (10 - (total % 10)) % 10
    return control == digits[10]


def _hamming(a: str, b: str) -> int:
    return sum(1 for x, y in zip(a, b) if x != y)


def _build_employee_id_correction(valid_pesels, unknown_ids):
    """Map unknown/corrupted employee ids in the timesheet to the closest
    valid PESEL found in employees.csv (data entry typos)."""
    correction = {}
    for uid in unknown_ids:
        if len(uid) != 11 or not uid.isdigit():
            continue
        best = min(valid_pesels, key=lambda v: _hamming(uid, v))
        if _hamming(uid, best) <= 3:
            correction[uid] = best
    return correction


def _fix_date(date_str: str) -> datetime.date:
    """Clamp impossible calendar days (e.g. Apr 31, Jun 31) to the last
    valid day of that month."""
    y, m, d = (int(p) for p in date_str.split("-"))
    last_day = calendar.monthrange(y, m)[1]
    if d > last_day:
        d = last_day
    return datetime.date(y, m, d)


def _parse_task_ids(raw: str):
    s = raw.strip().strip("[]")
    if not s:
        return []
    return [x.strip() for x in s.split(",") if x.strip()]


def _round_half_up(value: float) -> int:
    return int(Decimal(str(value)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def answer() -> dict:
    with open(EMPLOYEES_CSV, newline="", encoding="utf-8") as f:
        employees = list(csv.DictReader(f))
    hourly_rate = {r["PESEL"]: float(r["hourly_rate"]) for r in employees}
    valid_pesels = set(hourly_rate.keys())

    with open(TASKS_CSV, newline="", encoding="utf-8") as f:
        tasks = list(csv.DictReader(f))
    task_pay = {r["task_id"]: float(r["pay_per_completion"]) for r in tasks}
    valid_task_ids = set(task_pay.keys())

    with open(TIMESHEET_CSV, newline="", encoding="utf-8") as f:
        timesheet = list(csv.DictReader(f))

    unknown_ids = {r["employee_id"] for r in timesheet} - valid_pesels
    id_correction = _build_employee_id_correction(valid_pesels, unknown_ids)

    # month_totals[pesel][(year, month)] = accumulated salary (float, still
    # exact since hourly rates, hours, and task payouts are all integers)
    month_totals = defaultdict(lambda: defaultdict(float))

    for r in timesheet:
        emp = id_correction.get(r["employee_id"], r["employee_id"])
        if emp not in valid_pesels:
            # Unrecoverable / unknown employee reference -> exclude row.
            continue

        try:
            hours = float(r["hours_worked"])
        except ValueError:
            continue
        if hours < 0:
            continue

        date = _fix_date(r["date"])
        key = (date.year, date.month)

        task_ids = _parse_task_ids(r["performed_tasks"])
        bonus = sum(task_pay[t] for t in task_ids if t in valid_task_ids)

        month_totals[emp][key] += hours * hourly_rate[emp] + bonus

    result = {}
    for emp in valid_pesels:
        months = sorted(month_totals.get(emp, {}).keys())
        result[emp] = [_round_half_up(month_totals[emp][m]) for m in months]

    return result


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

